return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=(n > 1);','language'=>'fr_FR','project-id-version'=>'Next.js revalidate','pot-creation-date'=>'2026-08-20T13:45:46+00:00','po-revision-date'=>'2026-08-20 15:37+0200','x-generator'=>'Poedit 3.9','messages'=>['Next.js revalidate'=>'Next.js revalidate','https://github.com/superhuit-agency/nextjs-revalidate.git'=>'https://github.com/superhuit-agency/nextjs-revalidate.git','Next.js plugin allows you to purge & re-build the cached pages from the WordPress admin area. It also automatically purges & re-builds when a page/post/... is save or updated.'=>'Le plugin Next.js Revalidate vous permet de purger et de reconstruire les pages en cache depuis la zone d’administration de WordPress. Il purge et reconstruit aussi automatiquement lorsqu’une page/post/… est sauvegardée ou mise à jour.','superhuit'=>'superhuit','https://www.superhuit.ch'=>'https://www.superhuit.ch','Next.js revalidate is not keeping this site up to date — %1$d of the last %2$d revalidations failed. Content is still saved, but the front-end is serving pages which are quietly out of date.'=>'Next.js revalidate ne parvient pas à maintenir ce site à jour : %1$d des %2$d dernières purges ont échoué. Le contenu est toujours enregistré, mais le front-end affiche des pages qui sont, sans que l\'on s\'en rende compte, obsolètes.','Most recent error: %s.'=>'Dernière erreur : %s.','Other errors occurred as well.'=>'D\'autres erreurs se sont également produites.','Please contact a site administrator.'=>'Veuillez contacter un administrateur du site.','Check the Next.js revalidate settings'=>'Vérifier les paramètres Next.js Revalidate','the front-end could not be reached'=>'impossible d\'accéder au Frontend','the front-end rejected the secret'=>'le front-end a rejeté le secret','the front-end answered %s'=>'le front-end a répondu %s','The front-end answered without a status code.'=>'Le front-end a répondu sans code d\'état.','The front-end answered %d.'=>'The front-end answered %d.','Purge cache of post “%s”'=>'Purger le cache du post « %s »','Purge cache'=>'Vider le cache','Sorry, you are not allowed to purge the cache of this post.'=>'Désolé, vous n\'êtes pas autorisé(e) à vider le cache de cet article.','Admin top bar menuPurge this page'=>'Vider le cache','Admin top bar menuPurge the cache of the page currently being edited.'=>'Vider le cache de la page en cours d\'édition.','Purge caches'=>'Vider les caches','“%s” cache will be purged shortly.'=>'Le cache « %s » a été correctement purgé.','Unable to purge cache. Please try again or contact an administrator.'=>'Le cache n’a pas pu être vidé correctement. Veuillez réessayer ou contacter un administrateur.','%d cache will be purged shortly.'=>'%d cache sera bientôt purgé.' . "\0" . '%d caches seront bientôt purgés.','Admin top bar menuAll'=>'Tout','Admin top bar menuPurging all cache may take some time according to the number of pages to purge.'=>'La purge de tout le cache peut prendre un certain temps en fonction du nombre de pages à purger.','Revalidate all: nothing was queued, this site is not configured.'=>'Tout purger : aucun élément n\'était en file d\'attente, ce site n\'est pas configuré.','Purge all: %d pages added to purge. Please wait until all pages are purged.'=>'Purger tout : %d pages ajoutées à la file d’attente. Veuillez attendre que toutes les pages soient purgées.','Purging caches. Please wait… %s%s'=>'La purge des pages est en cours d’exécution. Veuillez patienter... %s%s','View purge caches queue'=>'Afficher la file d’attente de purge de cache','Queue correctly resetted.'=>'La file d’attente a été correctement réinitialisée.','Next.js revalidate settings'=>'Next.js revalidate paramètres','Next.js API'=>'Configuration de l’API Next.js','Allow purge all'=>'Autoriser la purge de tous','On menu update'=>'Vider les caches lors de la mise à jour d’un menu','Debug'=>'Débogage','Queue'=>'File d’attente','NextJS-Revalidate settings tabs'=>'Paramètres de Next.js revalidate','Purge queue'=>'File d’attente de purge','%d URL waiting to be purged'=>'%d URL en attente de purge' . "\0" . '%d URLs en attente de purge','Id'=>'Id','Priority'=>'Priorité','URL'=>'URL','Next.js API config'=>'Configuration de l’API Next.js','Revalidate domain'=>'Domaine','Revalidate path'=>'Chemin de purge','Optional. The route that revalidates a single path on the front-end. Leave empty for the default.'=>'Facultatif. L\'itinéraire qui revalide un seul chemin côté client. Laisser vide pour utiliser la valeur par défaut.','FSE revalidate path'=>'Chemin de purge du FSE','Optional. The route that invalidates the front-end’s FSE template snapshot. Leave empty for the default.'=>'Facultatif. Chemin d\'accès qui invalide l\'instantané du modèle FSE du front-end. Laisser vide pour utiliser la valeur par défaut.','Revalidate Secret'=>'Secret de revalidation','Allow purge all options'=>'Options de purge de tous les types','Define which post type has the option to have all posts purged in the admin bar.'=>'Définir quel type de post a l’option de purger tous les items dans la barre d’administration.','All post types'=>'Tous les types','Warning: according to the number of post types & posts for each post type this action can be very slow.'=>'Attention : en fonction du nombre de types de post et de posts pour chaque type, cette action peut être très lente.','On menu update options'=>'Paramètres de mise à jour de menu','Define which post type will be revalidated when updating a menu.'=>'Définir quel type de post sera vider lors de la mise à jour d’un menu.','Debug options'=>'Paramètres de débogage','Some configuration for easier debug.'=>'Quelques configurations pour faciliter le débogage.','Enable logs'=>'Activer les journaux','Logs will be saved to file located in <code>%s</code>'=>'Les journaux seront sauvegardés dans un fichier stocké dans <code>%s</code>','Next.js revalidate is not configured for this site: the revalidate domain and secret are both required before anything can be revalidated.'=>'Next.js revalidate n\'est pas configurée pour ce site : le domaine et la clé secrète de purge sont tous deux obligatoires avant de pouvoir procéder à une purge.','its revalidate domain and secret are missing'=>'le domaine et clé de purge sont manquants','its revalidate domain is missing'=>'le domaine de purge est manquants','its secret is missing'=>'le secret de purge est manquants','Next.js revalidate is not configured for this site — %s. Content is still saved, but every revalidation is refused: the front-end is never asked to rebuild its pages.'=>'Next.js revalidate n\'est pas configurée pour ce site — %s. Le contenu est toujours enregistré, mais chaque revalidation est refusée : le front-end n\'est jamais invité à reconstruire ses pages.','Configure Next.js revalidate'=>'Configurer Next.js revalidate','Admin top bar menuPurge caches'=>'Vider les caches','Please install composer dependencies for Next.js Revalidate to work'=>'Veuillez installer les dépendances du compositeur pour que Next.js Revalidate fonctionne','Next.js revalidate cannot set up the %s sites of this network in a single request, and it does not set up some of them and leave the rest without a queue table. Activate the plugin on each site individually instead.'=>'Next.js revalidate ne peut pas configurer les %s sites de ce réseau en une seule requête ; elle en configure certains et laisse les autres sans table de file d\'attente. Activez plutôt le plugin sur chaque site individuellement.','Plugin could not be activated'=>'Impossible d\'activer le plugin']];